from pathlib import Path
AU_TO_EV=27.211386245988
HARTREE_TO_CM=219474.6313705
def rd(p):
 q=Path(p)
 if not q.exists(): raise SystemExit('required file missing: '+p)
 return q.read_text(encoding='utf-8', errors='replace')
def num(x): return float(x.replace('D','E').replace('d','e'))
def src(f,loc=None):
 d={'filename':f}
 if loc is not None: d['location']=loc
 return d
out=rd('stdout.out'); inp=rd('job.inp'); geom=rd('geometry_used.xyz'); lines=out.splitlines(); states={}
pat_ev=re.compile(r'^[ 	]*STATE[ 	]+([0-9]+)[ 	]*:[ 	]*E[ 	]*=[ 	]*([-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[EeDd][-+]?[0-9]+)?)[ 	]+au[ 	]+([-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[EeDd][-+]?[0-9]+)?)[ 	]+eV', re.I)
pat_au=re.compile(r'^[ 	]*STATE[ 	]+([0-9]+)[ 	]*:[ 	]*E[ 	]*=[ 	]*([-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[EeDd][-+]?[0-9]+)?)[ 	]+au(?:[ 	]|$)', re.I)
for i,line in enumerate(lines,1):
 m=pat_ev.match(line)
 if m:
  n=int(m.group(1)); au=num(m.group(2)); ev=num(m.group(3))
  if n not in states: states[n]={'state':n,'energy_au':au,'energy_ev':ev,'energy_line':i,'fosc':None,'fosc_line':None}
  continue
 m=pat_au.match(line)
 if m:
  n=int(m.group(1)); au=num(m.group(2))
  if n not in states: states[n]={'state':n,'energy_au':au,'energy_ev':au*AU_TO_EV,'energy_line':i,'fosc':None,'fosc_line':None}
pat_osc=re.compile(r'Oscillator[ 	]+Strength[ 	]+for[ 	]+transition[ 	]+([0-9]+)[ 	]*:[ 	]*([-+]?(?:[0-9]+(?:[.][0-9]*)?|[.][0-9]+)(?:[EeDd][-+]?[0-9]+)?)', re.I)
for i,line in enumerate(lines,1):
 m=pat_osc.search(line)
 if m:
  n=int(m.group(1)); f=num(m.group(2))
  if n in states: states[n]['fosc']=f; states[n]['fosc_line']=i
abs_start=None
for i,line in enumerate(lines):
 u=line.upper()
 if 'ABSORPTION SPECTRUM' in u and 'ELECTRIC DIPOLE' in u:
  abs_start=i; break
if abs_start is not None:
 header_idx=None; fosc_idx=None
 for j in range(abs_start,min(abs_start+50,len(lines))):
  toks=lines[j].split(); low=[t.lower() for t in toks]
  if any('state' in t for t in low) and any(('fosc' in t or 'oscillator' in t) for t in low):
   header_idx=j
   for k,t in enumerate(low):
    if 'fosc' in t or 'oscillator' in t:
     fosc_idx=k; break
   break
 start=header_idx+1 if header_idx is not None else abs_start+1
 for j in range(start,min(start+120,len(lines))):
  parts=lines[j].strip().split()
  if not parts or not parts[0].isdigit(): continue
  n=int(parts[0])
  if n not in states: continue
  f=None
  if fosc_idx is not None and fosc_idx < len(parts):
   try: f=num(parts[fosc_idx])
   except ValueError: f=None
  if f is None:
   nums=[]
   for tok in parts[1:]:
    try: nums.append(num(tok))
    except ValueError: pass
   if len(nums)>=3: f=nums[2]
  if f is not None:
   states[n]['fosc']=f; states[n]['fosc_line']=j+1
if len(states)<5: raise SystemExit('fewer than five STATE records parsed: '+repr(sorted(states)))
reported=[]
for n in sorted(states)[:5]:
 s=states[n]
 if s['fosc'] is None: raise SystemExit('no oscillator strength parsed for state '+str(n)+'; parsed='+repr(sorted(states)))
 for k in ('energy_au','energy_ev','fosc'):
  if not math.isfinite(s[k]): raise SystemExit('non-finite '+k+' for state '+str(n))
 reported.append(s)
lowest=min(reported,key=lambda s:s['energy_ev']); strongest=max(reported,key=lambda s:s['fosc']); span=max(s['energy_ev'] for s in reported)-min(s['energy_ev'] for s in reported)
weak=[s for s in reported if abs(s['fosc'])<1e-6]
table_lines=chr(10).join('state '+str(s['state'])+': E='+format(s['energy_ev'],'.8f')+' eV, f='+format(s['fosc'],'.10g') for s in reported)
weak_text='none below 1e-6' if not weak else ', '.join('state '+str(s['state'])+' (f='+format(s['fosc'],'.6g')+')' for s in weak)
analysis_text='The lowest-energy root is state '+str(lowest['state'])+' at '+format(lowest['energy_ev'],'.6f')+' eV with f='+format(lowest['fosc'],'.8g')+'. The strongest electric-dipole transition is state '+str(strongest['state'])+' at '+format(strongest['energy_ev'],'.6f')+' eV with f='+format(strongest['fosc'],'.8g')+'. The five requested roots span '+format(span,'.6f')+' eV from '+format(min(s['energy_ev'] for s in reported),'.6f')+' to '+format(max(s['energy_ev'] for s in reported),'.6f')+' eV. Weak/near-zero roots (|f|<1e-6): '+weak_text+'. The low-energy states are distinguished from the stronger transition primarily by much smaller electric-dipole length-form oscillator strength; no configurational assignment is inferred beyond the response energies and f values. This is a vertical single-point TDDFT result, not an experimental absorption maximum or an adiabatic excitation energy.'
first_line=inp.splitlines()[0].strip() if inp.splitlines() else ''
method_text='Full linear-response TDDFT (TDA false) with CAM-B3LYP/def2-TZVP was selected. Full TDDFT avoids the TDA approximation and is affordable for this 10-atom system under the 4-core, 192 MB/process and 900 s limits. CAM-B3LYP is a range-separated hybrid appropriate for low-lying valence and weak transitions of acetone, while def2-TZVP gives a balanced triple-zeta polarized description. The managed actual input first line is: '+first_line
with open('absorption.csv','w',newline='',encoding='utf-8') as fh:
 w=csv.writer(fh); w.writerow(['state','energy_ev','oscillator_strength_length_form','energy_au','energy_cm-1'])
 for s in reported: w.writerow([s['state'],format(s['energy_ev'],'.12g'),format(s['fosc'],'.12g'),format(s['energy_au'],'.12g'),format(s['energy_au']*HARTREE_TO_CM,'.12g')])
excited_payload={'method':'CAM-B3LYP','basis':'def2-TZVP','response':'full linear-response TDDFT (TDA false)','charge':0,'multiplicity':1,'input_file':'job.inp','geometry_file':'geometry_used.xyz','raw_output':'stdout.out','states':reported,'all_parsed_states':[states[k] for k in sorted(states)]}
Path('excited_states.json').write_text(json.dumps(excited_payload,indent=2),encoding='utf-8')
Path('method_selection.md').write_text('# Method selection'+chr(10)+chr(10)+method_text+chr(10),encoding='utf-8')
Path('analysis_summary.md').write_text('# Vertical TDDFT analysis'+chr(10)+chr(10)+analysis_text+chr(10)+chr(10)+'Absorption table:'+chr(10)+chr(10)+table_lines+chr(10),encoding='utf-8')
obs=[]
obs.append({'name':'excitation_energies','value':[{'state':s['state'],'energy_ev':s['energy_ev']} for s in reported],'unit':'eV','sources':[src('stdout.out','line '+str(s['energy_line'])+' (STATE ... E= ... eV)') for s in reported]+[src('job.inp','managed actual input')],'formula':'Vertical TDDFT excitation energy; eV values taken from ORCA STATE records (or converted from au with 1 Eh = 27.211386245988 eV).','artifacts':['absorption.csv','excited_states.json'],'limitations':['Single-point vertical excitation at the prepared geometry; not an experimental absorption maximum or adiabatic excitation energy.','No geometry optimization was performed before this TDDFT response calculation.']})
obs.append({'name':'oscillator_strengths','value':[{'state':s['state'],'oscillator_strength_length_form':s['fosc']} for s in reported],'unit':'dimensionless','sources':[src('stdout.out','line '+str(s['fosc_line'])+' (electric-dipole length-form oscillator strength)') for s in reported]+[src('job.inp','managed actual input'),src('absorption.csv','length-form oscillator-strength table')],'formula':'ORCA electric-dipole length-form oscillator strength, reported dimensionless; all five requested roots retained including weak/near-zero values.','artifacts':['absorption.csv','excited_states.json'],'limitations':['Length-form oscillator strengths from the vertical TDDFT response; no experimental intensity calibration.','No vibrational broadening or solvent shift is applied.']})
obs.append({'name':'transition_analysis','value':analysis_text,'unit':None,'sources':[src('absorption.csv','all five length-form oscillator strengths'),src('stdout.out','energy and oscillator-strength records')],'formula':None,'artifacts':['analysis_summary.md','absorption.csv'],'limitations':['Analysis is limited to the calculated vertical energies and length-form oscillator strengths; no configurational assignment is inferred beyond those quantities.','This is not an experimental absorption spectrum.']})
obs.append({'name':'method_selection_rationale','value':method_text,'unit':None,'sources':[src('job.inp','actual managed input: '+first_line),src('stdout.out','ORCA response output')],'formula':None,'artifacts':['method_selection.md'],'limitations':['Method choice is a budget-aware scientific selection, not a benchmark against experimental spectra.']})
obs.append({'name':'random_seed','value':1701,'unit':None,'sources':[src('tddft_analysis.py','deterministic analysis script'),src('job.inp','deterministic ORCA input')],'formula':None,'artifacts':['tddft_analysis.py'],'limitations':['ORCA SCF/TDDFT and this Python analysis use no random sampling.','The structure.prepare tool exposes no seed parameter; if it uses randomness internally, seed 1701 cannot be enforced there and no seed-control claim is made for that step.']})
delivery_value={'geometry':'geometry_used.xyz (prepared initial geometry; single-point vertical TDDFT, no optimization)','actual_input':'job.inp','raw_response':'stdout.out','absorption_table':'absorption.csv','analysis_data':'excited_states.json','analysis_summary':'analysis_summary.md','method_selection':'method_selection.md','script':'tddft_analysis.py','states_reported':len(reported),'limitations':['Vertical single-point TDDFT energies and length-form oscillator strengths only.','No experimental peak assignment, adiabatic excitation energy, or HOMO-LUMO gap substitution.','No geometry optimization or frequency validation of the prepared geometry.']}
obs.append({'name':'delivery_report','value':delivery_value,'unit':None,'sources':[src('job.inp','actual managed input'),src('stdout.out','raw ORCA response'),src('geometry_used.xyz','prepared geometry used'),src('absorption.csv','absorption table'),src('excited_states.json','parsed response data'),src('analysis_summary.md','analysis narrative'),src('method_selection.md','method rationale'),src('tddft_analysis.py','generation/analysis script')],'formula':None,'artifacts':['geometry_used.xyz','job.inp','stdout.out','absorption.csv','excited_states.json','analysis_summary.md','method_selection.md','tddft_analysis.py'],'limitations':['Delivery is limited to the computed vertical response and its archived sources.']})
Path('observations.json').write_text(json.dumps({'version':1,'observations':obs},indent=2),encoding='utf-8')
print(json.dumps({'status':'ok','states_reported':len(reported),'files':['absorption.csv','excited_states.json','analysis_summary.md','method_selection.md','observations.json']}))

